f\\u0435\\u0442 \\u0433\\u0435\\u043d\\u0435\\u0440\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u043e\\u0447\\u0435\\u043d\\u044c \\u0434\\u043b\\u0438\\u043d\\u043d\\u044b\\u0435 \\u0441\\u043e\\u0433\\u043b\\u0430\\u0441\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0435 \\u043c\\u043d\\u043e\\u0433\\u043e\\u043c\\u0430\\u0441\\u0448\\u0442\\u0430\\u0431\\u043d\\u044b\\u0435 \\u0442\\u0440\\u0430\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438\\u0438 \\u0432 \\u043d\\u0430\\u0448\\u0435\\u0439 \\u043e\\u043f\\u0435\\u0440\\u0430\\u0446\\u0438\\u043e\\u043d\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438.\\n- **Tier 2 (\\u043e\\u0442\\u043d\\u043e\\u0441\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e setup_4).** \\u0415\\u0441\\u043b\\u0438 Tier 1 \\u043f\\u0440\\u043e\\u0439\\u0434\\u0435\\u043d: \\u0432\\u0435\\u0440\\u0434\\u0438\\u043a\\u0442 **\\u00ab\\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0430\\u0435\\u0442\\u00bb** \\u043f\\u0440\\u0438 (a) setup_5 \\u043d\\u0435 \\u0445\\u0443\\u0436\\u0435 setup_4 \\u043f\\u043e V(4096) (95% CI \\u0394V \\u0438\\u0441\\u043a\\u043b\\u044e\\u0447\\u0430\\u0435\\u0442 \\u00ab\\u0445\\u0443\\u0436\\u0435 \\u043d\\u0430 >0.05\\u00bb) \\u0438 \\u043d\\u0435 \\u0445\\u0443\\u0436\\u0435 \\u043f\\u043e \\u0394B (95% CI), \\u0418 \\u0445\\u043e\\u0442\\u044f \\u0431\\u044b \\u043e\\u0434\\u043d\\u043e \\u0438\\u0437: V-\\u0432\\u044b\\u0438\\u0433\\u0440\\u044b\\u0448 \\u0394V \\u2265 0.10 (CI\\u22600), \\u0438\\u043b\\u0438 \\u0443\\u043b\\u0443\\u0447\\u0448\\u0435\\u043d\\u0438\\u0435 \\u0394B \\u2265 0.05, \\u0438\\u043b\\u0438 \\u22652\\u00d7 \\u043f\\u0440\\u0435\\u0438\\u043c\\u0443\\u0449\\u0435\\u0441\\u0442\\u0432\\u043e \\u043f\\u043e \\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u0438+\\u043f\\u0430\\u043c\\u044f\\u0442\\u0438 \\u043d\\u0430 8192. **Mixed/partial**: \\u0437\\u043d\\u0430\\u0447\\u0438\\u043c\\u043e\\u0435 \\u043f\\u0440\\u043e\\u0438\\u0433\\u0440\\u044b\\u0432\\u0430\\u043d\\u0438\\u0435 \\u043f\\u043e V \\u0438\\u043b\\u0438 \\u0394B \\u043f\\u0440\\u0438 \\u0432\\u044b\\u0438\\u0433\\u0440\\u044b\\u0448\\u0435 \\u043f\\u043e \\u043c\\u0430\\u0441\\u0448\\u0442\\u0430\\u0431\\u0438\\u0440\\u0443\\u0435\\u043c\\u043e\\u0441\\u0442\\u0438 \\u2192 \\u00ab\\u0447\\u0430\\u0441\\u0442\\u0438\\u0447\\u043d\\u043e: \\u0434\\u043b\\u0438\\u043d\\u043d\\u0435\\u0435/\\u0434\\u0435\\u0448\\u0435\\u0432\\u043b\\u0435, \\u043d\\u043e \\u0441 \\u043f\\u043e\\u0442\\u0435\\u0440\\u0435\\u0439 \\u043a\\u043e\\u043d\\u0441\\u0438\\u0441\\u0442\\u0435\\u043d\\u0442\\u043d\\u043e\\u0441\\u0442\\u0438\\u00bb. \\u0415\\u0441\\u043b\\u0438 \\u043f\\u0430\\u0440\\u0438\\u0442\\u0435\\u0442 \\u043f\\u043e \\u0432\\u0441\\u0435\\u043c \\u043c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0430\\u043c, \\u043d\\u043e \\u0441\\u0442\\u0440\\u043e\\u0433\\u043e \\u043b\\u0443\\u0447\\u0448\\u0435 \\u043c\\u0430\\u0441\\u0448\\u0442\\u0430\\u0431\\u0438\\u0440\\u0443\\u0435\\u043c\\u043e\\u0441\\u0442\\u044c \\u2192 \\u00ab\\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0430\\u0435\\u0442 (\\u043f\\u043e \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442\\u0438\\u0432\\u043d\\u043e\\u0441\\u0442\\u0438)\\u00bb.\\n- \\u0421\\u0442\\u0430\\u0442\\u0438\\u0441\\u0442\\u0438\\u043a\\u0430: \\u0441\\u0440\\u0435\\u0434\\u043d\\u0435\\u0435 \\u043f\\u043e \\u0441\\u0438\\u0434\\u0430\\u043c \\u00b1 \\u0440\\u0430\\u0437\\u0431\\u0440\\u043e\\u0441; 95% CI \\u0431\\u0443\\u0442\\u0441\\u0442\\u0440\\u044d\\u043f\\u043e\\u043c \\u043f\\u043e \\u0441\\u044d\\u043c\\u043f\\u043b\\u0430\\u043c \\u0432\\u043d\\u0443\\u0442\\u0440\\u0438 \\u0441\\u0438\\u0434\\u0430 \\u0438 \\u043f\\u043e \\u0441\\u0438\\u0434\\u0430\\u043c; \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u043e worst-\\u0441\\u0438\\u0434 (\\u043d\\u0438\\u043a\\u0430\\u043a\\u0438\\u0445 \\u00ab\\u043f\\u043e \\u043b\\u0443\\u0447\\u0448\\u0435\\u043c\\u0443 \\u0441\\u0438\\u0434\\u0443\\u00bb).\\n\\n---\\n\\n**2) \\u0422\\u043e\\u0447\\u043d\\u0430\\u044f \\u043a\\u043e\\u043d\\u0444\\u0438\\u0433\\u0443\\u0440\\u0430\\u0446\\u0438\\u044f \\u0434\\u0432\\u0443\\u0445 \\u0432\\u0435\\u0442\\u043e\\u043a**\\n\\n\\u041e\\u0431\\u0449\\u0430\\u044f \\u0430\\u0440\\u0445\\u0438\\u0442\\u0435\\u043a\\u0442\\u0443\\u0440\\u0430 (\\u0442\\u0440\\u0430\\u0435\\u043a\\u0442\\u043e\\u0440\\u043d\\u0430\\u044f \\u0430\\u0434\\u0430\\u043f\\u0442\\u0430\\u0446\\u0438\\u044f SiT, \\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432\\u0430 \\u0432 \\u043e\\u0431\\u0435\\u0438\\u0445 \\u0432\\u0435\\u0442\\u043a\\u0430\\u0445, \\u043a\\u0440\\u043e\\u043c\\u0435 \\u0441\\u043b\\u043e\\u044f time-mixing):\\n- \\u0414\\u0430\\u043d\\u043d\\u044b\\u0435: \\u043f\\u043e\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u044c \\u0441\\u043e\\u0441\\u0442\\u043e\\u044f\\u043d\\u0438\\u0439 x \\u2208 R^{T\\u00d7C}, C=5 \\u043a\\u0430\\u043d\\u0430\\u043b\\u043e\\u0432 (\\u0444\\u0438\\u0437\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0435 \\u043f\\u0435\\u0440\\u0435\\u043c\\u0435\\u043d\\u043d\\u044b\\u0435).\\n- \\u0412\\u0445\\u043e\\u0434: \\u043b\\u0438\\u043d\\u0435\\u0439\\u043d\\u044b\\u0439 patch-\\u044d\\u043c\\u0431\\u0435\\u0434\\u0434\\u0438\\u043d\\u0433 x\\u2192R^{T\\u00d7D} (D=128) + \\u043e\\u0431\\u0443\\u0447\\u0430\\u0435\\u043c\\u044b\\u0439 \\u043f\\u043e\\u0437\\u0438\\u0446\\u0438\\u043e\\u043d\\u043d\\u044b\\u0439 \\u044d\\u043c\\u0431\\u0435\\u0434\\u0434\\u0438\\u043d\\u0433 R^{T\\u00d7D}; \\u043f\\u043b\\u044e\\u0441 \\u00ab\\u0438\\u043d\\u0442\\u0435\\u0440\\u043f\\u043e\\u043b\\u044f\\u043d\\u0442\\u043d\\u043e\\u0435 \\u0432\\u0440\\u0435\\u043c\\u044f\\u00bb t\\u2208[0,1] \\u0447\\u0435\\u0440\\u0435\\u0437 \\u0441\\u0438\\u043d\\u0443\\u0441\\u043e\\u0438\\u0434\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u044d\\u043c\\u0431\\u0435\\u0434\\u0434\\u0438\\u043d\\u0433 + MLP \\u2192 adaLN-\\u043c\\u043e\\u0434\\u0443\\u043b\\u044f\\u0446\\u0438\\u044f (scale/shift/gate), \\u043a\\u0430\\u043a \\u0432 DiT/SiT.\\n- \\u0411\\u043b\\u043e\\u043a (N=6 \\u0441\\u043b\\u043e\\u0451\\u0432, D=128):\\n  1. adaLN \\u043e\\u0442 t;\\n  2. **time-mixing \\u0441\\u043b\\u043e\\u0439 (\\u0412\\u0410\\u0420\\u042c\\u0418\\u0420\\u0423\\u0415\\u0422\\u0421\\u042f)** \\u2014 \\u0441\\u043c. \\u043d\\u0438\\u0436\\u0435;\\n  3. per-token MLP (D\\u21924D\\u2192D, GELU) + adaLN \\u2014 \\u00ab\\u043f\\u0440\\u043e\\u0441\\u0442\\u0440\\u0430\\u043d\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e\\u0435/\\u043f\\u0440\\u0438\\u0437\\u043d\\u0430\\u043a\\u043e\\u0432\\u043e\\u0435 \\u043f\\u0435\\u0440\\u0435\\u043c\\u0435\\u0448\\u0438\\u0432\\u0430\\u043d\\u0438\\u0435\\u00bb (\\u0432 1D \\u0443 \\u043d\\u0430\\u0441 \\u043d\\u0435\\u0442 \\u0438\\u0441\\u0442\\u0438\\u043d\\u043d\\u043e\\u0433\\u043e \\u043f\\u0440\\u043e\\u0441\\u0442\\u0440\\u0430\\u043d\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e\\u0433\\u043e \\u0438\\u0437\\u043c\\u0435\\u0440\\u0435\\u043d\\u0438\\u044f \\u0442\\u043e\\u043a\\u0435\\u043d\\u043e\\u0432, \\u043f\\u043e\\u044d\\u0442\\u043e\\u043c\\u0443 \\u0440\\u043e\\u043b\\u044c spatial-attention DiT \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u044f\\u0435\\u0442 per-token MLP; \\u044d\\u0442\\u043e \\u043e\\u043f\\u0435\\u0440\\u0430\\u0446\\u0438\\u043e\\u043d\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f, \\u043d\\u0435 \\u043a\\u043e\\u0434 \\u0438\\u0441\\u0442\\u043e\\u0447\\u043d\\u0438\\u043a\\u0430);\\n  4. Residual + LayerNorm + adaLN-\\u0433\\u0435\\u0439\\u0442 \\u03b1(t) \\u0432\\u043e\\u043a\\u0440\\u0443\\u0433 \\u043a\\u0430\\u0436\\u0434\\u043e\\u0433\\u043e \\u043f\\u043e\\u0434\\u0441\\u043b\\u043e\\u044f.\\n- \\u0413\\u043e\\u043b\\u043e\\u0432\\u0430: \\u0444\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 LayerNorm + Linear \\u2192 \\u043f\\u0440\\u0435\\u0434\\u0441\\u043a\\u0430\\u0437\\u0430\\u043d\\u0438\\u0435 \\u043f\\u043e\\u043b\\u044f v_\\u03b8(x_t,t) \\u2208 R^{T\\u00d7C}. \\u041e\\u0431\\u0443\\u0447\\u0435\\u043d\\u0438\\u0435 \\u2014 \\u0438\\u043d\\u0442\\u0435\\u0440\\u043f\\u043e\\u043b\\u044f\\u043d\\u0442\\u044b/flow-matching (\\u043a\\u0430\\u043a SiT): x_t = \\u0438\\u043d\\u0442\\u0435\\u0440\\u043f\\u043e\\u043b\\u044f\\u0446\\u0438\\u044f \\u043c\\u0435\\u0436\\u0434\\u0443 \\u0434\\u0430\\u043d\\u043d\\u044b\\u043c\\u0438 x_0 \\u0438 \\u0448\\u0443\\u043c\\u043e\\u043c x_1 (\\u0441\\u0442ox\\u0430\\u0441\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0438\\u043d\\u0442\\u0435\\u0440\\u043f\\u043e\\u043b\\u044f\\u043d\\u0442), loss = MSE(\\u2016v_\\u03b8 \\u2212 (x_1\\u2212x_0)\\u2016\\u00b2). \\u0413\\u0435\\u043d\\u0435\\u0440\\u0430\\u0446\\u0438\\u044f: \\u0438\\u0437 \\u0448\\u0443\\u043c\\u0430 x_1 \\u0438\\u043d\\u0442\\u0435\\u0433\\u0440\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 v_\\u03b8 \\u043f\\u043e t\\u2208[0,1] (ODE-\\u0441\\u044d\\u043c\\u043f\\u043b\\u0435\\u0440, \\u043d\\u0430\\u043f\\u0440. RK4/Euler \\u0441 100 \\u0448\\u0430\\u0433\\u0430\\u043c\\u0438 \\u043f\\u043e t). \\u042d\\u0442\\u043e \\u0432\\u0430\\u0436\\u043d\\u043e: \\u0442\\u0440\\u0430\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438\\u044f \\u0433\\u0435\\u043d\\u0435\\u0440\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u0446\\u0435\\u043b\\u0438\\u043a\\u043e\\u043c (\\u043d\\u0435 \\u0430\\u0432\\u0442\\u043e\\u0440\\u0435\\u0433\\u0440\\u0435\\u0441\\u0441\\u0438\\u0432\\u043d\\u043e \\u043f\\u043e \\u0448\\u0430\\u0433\\u0430\\u043c), \\u043f\\u043e\\u044d\\u0442\\u043e\\u043c\\u0443 \\u043d\\u0435\\u043a\\u0430\\u0443\\u0437\\u0430\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u044c \\u0432 train \\u0438 inference \\u043d\\u0435\\u043f\\u0440\\u043e\\u0442\\u0438\\u0432\\u043e\\u0440\\u0435\\u0447\\u0438\\u0432\\u0430.\\n\\n**setup_4 \\u2014 time attention:** multi-head self-attention (heads=4, head_dim=32) \\u043f\\u043e \\u043e\\u0441\\u0438 \\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u0438 \\u0442\\u043e\\u043a\\u0435\\u043d\\u043e\\u0432, CAUSAL mask (\\u0430\\u0432\\u0442\\u043e\\u0440\\u0435\\u0433\\u0440\\u0435\\u0441\\u0441\\u0438\\u0432\\u043d\\u043e \\u043f\\u043e \\u043e\\u0441\\u0438 \\u0432\\u0440\\u0435\\u043c\\u0435\\u043d\\u0438 \\u0442\\u0440\\u0430\\u0435\\u043a\\u0442\\u043e\\u0440\\u0438\\u0438), O(T\\u00b2\\u00b7D) \\u043d\\u0430 \\u0441\\u043b\\u043e\\u0439. \\u041b\\u043e\\u0433\\u0438\\u043a\\u0430: \\u00ab\\u0438\\u0441\\u0445\\u043e\\u0434\\u043d\\u044b\\u0439 time attention\\u00bb \\u2014 \\u043f\\u0440\\u0435\\u0434\\u043f\\u043e\\u043b\\u043e\\u0436\\u0435\\u043d\\u0438\\u0435 \\u043e\\u0431 \\u043e\\u043f\\u0435\\u0440\\u0430\\u0446\\u0438\\u043e\\u043d\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438: \\u043a\\u0430\\u0443\\u0437\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 masked time attention, \\u0447\\u0442\\u043e\\u0431\\u044b \\u043a\\u043e\\u043d\\u0442\\u0440\\u0430\\u0441\\u0442 \\u00ab\\u043a\\u0430\\u0443\\u0437\\u0430\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u044c vs \\u043d\\u0435\\u043a\\u0430\\u0443\\u0437\\u0430\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u044c\\u00bb \\u0431\\u044b\\u043b \\u0447\\u0438\\u0441\\u0442\\u044b\\u043c (\\u0441\\u043c. \\u0434\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u0435 A1 \\u0438 \\u043d\\u0435\\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0451\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c U1).\\n\\n**setup_5 \\u2014 \\u043d\\u0435\\u043a\\u0430\\u0443\\u0437\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 Hyena (\\u0432\\u043c\\u0435\\u0441\\u0442\\u043e time attention), \\u0442\\u043e\\u0447\\u043d\\u0430\\u044f \\u0440\\u0435\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f:**\\n- \\u0422\\u0440\\u0438 \\u043b\\u0438\\u043d\\u0435\\u0439\\u043d\\u044b\\u0435 \\u043f\\u0440\\u043e\\u0435\\u043a\\u0446\\u0438\\u0438 \\u0432\\u0445\\u043e\\u0434\\u0430 x\\u2208R^{T\\u00d7D}: value-\\u043f\\u0