\\u043e\\u0431\\u0438\\u0440\\u0430\\u0435\\u0442\\u0441\\u044f/\\u0441\\u0447\\u0438\\u0442\\u044b\\u0432\\u0430\\u0435\\u0442\\u0441\\u044f \\u0442\\u0430\\u043a, \\u0447\\u0442\\u043e \\u0438\\u043d\\u0434\\u0435\\u043a\\u0441 0 \\u0441\\u043e\\u043e\\u0442\\u0432\\u0435\\u0442\\u0441\\u0442\\u0432\\u0443\\u0435\\u0442 \\u0442\\u0435\\u043a\\u0443\\u0449\\u0435\\u043c\\u0443 \\u0448\\u0430\\u0433\\u0443 (kernel peak \\u0432 \\u043f\\u043e\\u0437\\u0438\\u0446\\u0438\\u0438 0); \\u044d\\u043a\\u0432\\u0438\\u0432\\u0430\\u043b\\u0435\\u043d\\u0442 fftshift-\\u0432\\u044b\\u0440\\u0430\\u0432\\u043d\\u0438\\u0432\\u0430\\u043d\\u0438\\u044f \\u0444\\u0438\\u043b\\u044c\\u0442\\u0440\\u0430.\\n  2. **\\u0414\\u0432\\u0443\\u0441\\u0442\\u043e\\u0440\\u043e\\u043d\\u043d\\u044f\\u044f \\u0441\\u0438\\u043c\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u043d\\u0430\\u044f pad-\\u0441\\u0445\\u0435\\u043c\\u0430:** x \\u0438 v \\u043f\\u0430\\u0434\\u0434\\u044f\\u0442\\u0441\\u044f \\u043d\\u0443\\u043b\\u044f\\u043c\\u0438 \\u043d\\u0430 (T\\u22121) \\u0441\\u043b\\u0435\\u0432\\u0430 \\u0438 (T\\u22121) \\u0441\\u043f\\u0440\\u0430\\u0432\\u0430 \\u2192 \\u0434\\u043b\\u0438\\u043d\\u0430 L_fft = 3T\\u22122 (\\u043e\\u043a\\u0440\\u0443\\u0433\\u043b\\u044f\\u0435\\u0442\\u0441\\u044f \\u0434\\u043e \\u0443\\u0434\\u043e\\u0431\\u043d\\u043e\\u0439 \\u0441\\u0442\\u0435\\u043f\\u0435\\u043d\\u0438/\\u0444\\u0430\\u043a\\u0442\\u043e\\u0440\\u0430 \\u0434\\u043b\\u044f FFT); circular-convolution \\u00d7 (\\u043f\\u043e\\u043b\\u043d\\u0430\\u044f \\u043b\\u0438\\u043d\\u0435\\u0439\\u043d\\u0430\\u044f \\u0441\\u0432\\u0451\\u0440\\u0442\\u043a\\u0430), \\u0437\\u0430\\u0442\\u0435\\u043c \\u0446\\u0435\\u043d\\u0442\\u0440\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 crop \\u0434\\u043b\\u0438\\u043d\\u044b T \\u2192 \\u043a\\u0430\\u0436\\u0434\\u044b\\u0439 \\u0432\\u044b\\u0445\\u043e\\u0434 = \\u0441\\u0438\\u043c\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u043d\\u043