na \\u22481.2\\u20131.5 \\u0441 \\u0443\\u0447\\u0451\\u0442\\u043e\\u043c FFT-\\u043e\\u0432\\u0435\\u0440\\u0445\\u0435\\u0434\\u0430); \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d \\u0432 1 \\u043f\\u043e\\u0442\\u043e\\u043a \\u0438 224 \\u043f\\u043e\\u0442\\u043e\\u043a\\u0430.\\n- **\\u0410\\u0433\\u0440\\u0435\\u0433\\u0430\\u0446\\u0438\\u044f \\u043f\\u043e \\u0441\\u0438\\u0434\\u0430\\u043c:** \\u043f\\u0435\\u0440\\u0432\\u0438\\u0447\\u043d\\u043e \\u0441\\u0440\\u0435\\u0434\\u043d\\u0435\\u0435 \\u043f\\u043e \\u0441\\u0438\\u0434\\u0430\\u043c \\u00b1 std; \\u0431\\u0443\\u0442\\u0441\\u0442\\u0440\\u044d\\u043f-95% CI \\u043f\\u043e \\u0441\\u044d\\u043c\\u043f\\u043b\\u0430\\u043c (\\u043f\\u0443\\u043b \\u0432\\u043d\\u0443\\u0442\\u0440\\u0438 \\u0441\\u0438\\u0434\\u0430, \\u0437\\u0430\\u0442\\u0435\\u043c \\u043f\\u043e \\u0441\\u0438\\u0434\\u0430\\u043c); \\u043e\\u0442\\u0434\\u0435\\u043b\\u044c\\u043d\\u043e worst-\\u0441\\u0438\\u0434. \\u0420\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442 \\u043f\\u0440\\u0438\\u043d\\u0438\\u043c\\u0430\\u0435\\u0442\\u0441\\u044f \\u043f\\u043e \\u043f\\u0440\\u0435\\u0434\\u0437\\u0430\\u0440\\u0435\\u0433\\u0438\\u0441\\u0442\\u0440. \\u043f\\u0440\\u0430\\u0432\\u0438\\u043b\\u0443 \\u00a71, \\u0431\\u0435\\u0437 p-hacking \\u0438 \\u0432\\u044b\\u0431\\u043e\\u0440\\u0430 \\u00ab\\u043b\\u0443\\u0447\\u0448\\u0435\\u0433\\u043e \\u0441\\u0438\\u0434\\u0430\\u00bb.\\n\\n---\\n\\n**6) \\u041e\\u0441\\u0443\\u0449\\u0435\\u0441\\u0442\\u0432\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c \\u0432 \\u0441\\u0440\\u0435\\u0434\\u0435 (\\u043e\\u0446\\u0435\\u043d\\u043a\\u0430 \\u0431\\u044e\\u0434\\u0436\\u0435\\u0442\\u0430)**\\n\\n\\u0420\\u0435\\u0430\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u044c \\u0441\\u0440\\u0435\\u0434\\u044b: CPU-only (224 \\u044f\\u0434\\u0440\\u0430), ~2 TiB RAM (~1.9 TiB \\u0434\\u043e\\u0441\\u0442\\u0443\\u043f\\u043d\\u043e), ~20 \\u0413\\u0411 \\u0441\\u0432\\u043e\\u0431\\u043e\\u0434\\u043d\\u043e \\u043d\\u0430 \\u0432\\u043e\\u0440\\u043a\\u0441\\u043f\\u0435\\u0439\\u0441\\u0435, Python 3.14.4, \\u0411\\u0415\\u0417 numpy/scipy/torch \\u0438 \\u0411\\u0415\\u0417 \\u0441\\u0435\\u0442\\u0438 \\u2192 \\u0443\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043a\\u0430 \\u043f\\u0430\\u043a\\u0435\\u0442\\u043e\\u0432 pip \\u043d\\u0435\\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u043d\\u0430. \\u0421\\u043e\\u0433\\u043b\\u0430\\u0441\\u043d\\u043e track.md (\\u00abrepositories and compute are not required\\u00bb) \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d \\u044f\\u0432\\u043b\\u044f\\u0435\\u0442\\u0441\\u044f \\u043f\\u043e\\u0441\\u0442\\u0430\\u0432\\u043b\\u044f\\u0435\\u043c\\u044b\\u043c \\u0430\\u0440\\u0442\\u0435\\u0444\\u0430\\u043a\\u0442\\u043e\\u043c; \\u043d\\u0438\\u0436\\u0435 \\u2014 \\u0447\\u0442\\u043e \\u043d\\u0443\\u0436\\u043d\\u043e, \\u0415\\u0421\\u041b\\u0418 \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u044f\\u0442\\u044c.\\n\\n- \\u0422\\u0440\\u0435\\u0431\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 \\u043a \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u044e: \\u043f\\u043e\\u0434\\u0433\\u043e\\u0442\\u043e\\u0432\\u043b\\u0435\\u043d\\u043d\\u0430\\u044f \\u0441\\u0440\\u0435\\u0434\\u0430 \\u0441 torch \\u0418\\u041b\\u0418 numpy+scipy (FFT). \\u041e\\u0434\\u0438\\u043d \\u0438\\u0437 \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442\\u043e\\u0432: \\u043a\\u043e\\u043c\\u043f\\u0430\\u043a\\u0442\\u043d\\u0430\\u044f \\u0447\\u0438\\u0441\\u0442\\u0430\\u044f NumPy/Cython FFT-Hyena (Hyena \\u2014 \\u0441\\u0432\\u0435\\u0440\\u0442\\u043e\\u0447\\u043d\\u044b\\u0439 \\u043e\\u043f\\u0435\\u0440\\u0430\\u0442\\u043e\\u0440, \\u0440\\u0435\\u0430\\u043b\\u0438\\u0437\\u0443\\u0435\\u043c \\u0431\\u0435\\u0437 torch; attention \\u2014 \\u0442\\u043e\\u0436\\u0435 \\u043d\\u0430 NumPy). \\u0420\\u0435\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f \\u043d\\u0430 \\u00